package com.example.starter.restitution.service;

import org.springframework.stereotype.Component;

import java.util.function.Supplier;

/**
 * 写操作幂等执行：以全局 requestId + 操作者为键，
 * 同键同操作者同参重放首次结果，异参 409；业务失败回滚且不占键。
 */
@Component
public class IdempotentExecutor {

    /**
     * 在同一事务内执行业务并落幂等记录。
     *
     * @param requestId    X-Request-Id
     * @param actor        X-Actor-Id
     * @param operation    操作标识（HTTP 方法+路径模板）
     * @param requestBody  请求参数对象（参与指纹，集合按规范排序）
     * @param responseType 首次结果/重放结果的响应类型
     * @param action       首次执行的业务动作
     */
    public <T> T execute(String requestId, String actor, String operation,
                         Object requestBody, Class<T> responseType, Supplier<T> action) {
        return action.get();
    }
}

