-- 藏品归还裁决领域建表脚本（H2 MODE=MySQL 下执行；MySQL 8 同样兼容）

CREATE TABLE IF NOT EXISTS restitution_case (
    id          VARCHAR(64)  NOT NULL,
    status      VARCHAR(16)  NOT NULL,
    version     BIGINT       NOT NULL,
    created_at  BIGINT       NOT NULL,
    decided_at  BIGINT       NULL,
    CONSTRAINT pk_restitution_case PRIMARY KEY (id)
);
COMMENT ON COLUMN restitution_case.status IS '案件状态：OPEN 可写入，DECIDED 已终态裁决冻结';
COMMENT ON COLUMN restitution_case.version IS '案件乐观版本，登记/撤回主张、证据增撤、首次批准、裁决均加一';
COMMENT ON COLUMN restitution_case.decided_at IS '裁决时间（epoch 毫秒，Asia/Shanghai 业务时区），未裁决为空';

CREATE TABLE IF NOT EXISTS case_item (
    case_id     VARCHAR(64)  NOT NULL,
    item_no     VARCHAR(64)  NOT NULL,
    ord         INT          NOT NULL,
    CONSTRAINT pk_case_item PRIMARY KEY (case_id, item_no)
);
COMMENT ON TABLE case_item IS '案件藏品编号清单，1 至 10 个，案内唯一；ord 为登记顺序';

CREATE TABLE IF NOT EXISTS claim (
    id            BIGINT AUTO_INCREMENT NOT NULL,
    case_id       VARCHAR(64)  NOT NULL,
    claim_key     VARCHAR(64)  NOT NULL,
    applicant     VARCHAR(128) NOT NULL,
    statement     VARCHAR(2000) NOT NULL,
    withdrawn     BOOLEAN      NOT NULL,
    version       BIGINT       NOT NULL,
    created_at    BIGINT       NOT NULL,
    withdrawn_at  BIGINT       NULL,
    CONSTRAINT pk_claim PRIMARY KEY (id),
    CONSTRAINT uk_claim_case_key UNIQUE (case_id, claim_key)
);
COMMENT ON TABLE claim IS '归还主张：案内 claimKey 唯一；withdrawn=1 表示已撤回且不可恢复，内容不可改';
COMMENT ON COLUMN claim.version IS '主张当前证据版本，证据追加/撤销加一，初始 0';
COMMENT ON COLUMN claim.withdrawn_at IS '撤回时间（epoch 毫秒），未撤回为空';

CREATE TABLE IF NOT EXISTS claim_item (
    claim_id    BIGINT       NOT NULL,
    item_no     VARCHAR(64)  NOT NULL,
    ord         INT          NOT NULL,
    CONSTRAINT pk_claim_item PRIMARY KEY (claim_id, item_no)
);
COMMENT ON TABLE claim_item IS '主张覆盖的藏品子集，登记后不可变更；ord 为登记顺序';

CREATE TABLE IF NOT EXISTS evidence (
    id            BIGINT AUTO_INCREMENT NOT NULL,
    case_id       VARCHAR(64)  NOT NULL,
    claim_id      BIGINT       NOT NULL,
    evidence_key  VARCHAR(64)  NOT NULL,
    summary       VARCHAR(2000) NOT NULL,
    version       BIGINT       NOT NULL,
    active        BOOLEAN      NOT NULL,
    created_at    BIGINT       NOT NULL,
    revoked_at    BIGINT       NULL,
    CONSTRAINT pk_evidence PRIMARY KEY (id),
    CONSTRAINT uk_evidence_case_key UNIQUE (case_id, evidence_key)
);
COMMENT ON TABLE evidence IS '证据：案内 evidenceKey 唯一，每主张至多 20 份（含历史）；撤销保留历史';
COMMENT ON COLUMN evidence.version IS '该证据创建时主张所处的证据版本';
COMMENT ON COLUMN evidence.active IS '1 有效；0 已撤销（历史保留，批准失效）';

CREATE TABLE IF NOT EXISTS approval (
    id               BIGINT AUTO_INCREMENT NOT NULL,
    case_id          VARCHAR(64)  NOT NULL,
    claim_id         BIGINT       NOT NULL,
    evidence_version BIGINT       NOT NULL,
    reviewer         VARCHAR(128) NOT NULL,
    created_at       BIGINT       NOT NULL,
    CONSTRAINT pk_approval PRIMARY KEY (id),
    CONSTRAINT uk_approval_claim_version_reviewer UNIQUE (claim_id, evidence_version, reviewer)
);
COMMENT ON TABLE approval IS '评审人对主张某证据版本的批准；证据版本推进或证据撤销后旧批准失效';

CREATE TABLE IF NOT EXISTS frozen_item (
    case_id    VARCHAR(64)  NOT NULL,
    item_no    VARCHAR(64)  NOT NULL,
    claim_key  VARCHAR(64)  NOT NULL,
    applicant  VARCHAR(128) NOT NULL,
    ord        INT          NOT NULL,
    CONSTRAINT pk_frozen_item PRIMARY KEY (case_id, item_no)
);
COMMENT ON TABLE frozen_item IS '裁决冻结：藏品编号到中选主张/申请人的对应关系；ord 为全案藏品顺序';

CREATE TABLE IF NOT EXISTS frozen_claim (
    case_id    VARCHAR(64)  NOT NULL,
    claim_key  VARCHAR(64)  NOT NULL,
    applicant  VARCHAR(128) NOT NULL,
    statement  VARCHAR(2000) NOT NULL,
    CONSTRAINT pk_frozen_claim PRIMARY KEY (case_id, claim_key)
);
COMMENT ON TABLE frozen_claim IS '裁决冻结：中选主张快照';

CREATE TABLE IF NOT EXISTS frozen_evidence (
    case_id       VARCHAR(64)  NOT NULL,
    claim_key     VARCHAR(64)  NOT NULL,
    evidence_key  VARCHAR(64)  NOT NULL,
    summary       VARCHAR(2000) NOT NULL,
    version       BIGINT       NOT NULL,
    CONSTRAINT pk_frozen_evidence PRIMARY KEY (case_id, evidence_key)
);
COMMENT ON TABLE frozen_evidence IS '裁决冻结：中选主张在裁决时的全部有效证据快照';

CREATE TABLE IF NOT EXISTS frozen_approval (
    case_id          VARCHAR(64)  NOT NULL,
    claim_key        VARCHAR(64)  NOT NULL,
    evidence_version BIGINT       NOT NULL,
    reviewer         VARCHAR(128) NOT NULL,
    created_at       BIGINT       NOT NULL,
    CONSTRAINT pk_frozen_approval PRIMARY KEY (case_id, claim_key, evidence_version, reviewer)
);
COMMENT ON TABLE frozen_approval IS '裁决冻结：支撑裁决的当前版本批准快照（每主张两名不同评审人）';

CREATE TABLE IF NOT EXISTS request_record (
    request_id    VARCHAR(64)  NOT NULL,
    actor         VARCHAR(128) NOT NULL,
    request_hash  VARCHAR(64)  NOT NULL,
    status_code   INT          NOT NULL,
    response_body CLOB         NOT NULL,
    created_at    BIGINT       NOT NULL,
    CONSTRAINT pk_request_record PRIMARY KEY (request_id, actor)
);
